  "@type": "Recipe",
  "name": "French Toast",
  "author": {
    "@type": "Person",
    "name": "Nagi | RecipeTin Eats"
  },
  "description": "Recipe video above.&nbsp;A recipe everyone should know! Made for using up leftover bread, but if you want the ultimate French Toast experience, use brioche bread (pictured in post). There’s no need to use sugar if you’re dousing with maple syrup – plus it burns easily. Best made with stale bread, otherwise, see Note 1.&nbsp;",
  "datePublished": "2019-02-23T14:11:54+00:00",
  "image": [
    "https://www.recipetineats.com/tachyon/2014/06/French-Toast_3.jpg",
    "https://www.recipetineats.com/tachyon/2014/06/French-Toast_3.jpg?resize=500%2C500",
    "https://www.recipetineats.com/tachyon/2014/06/French-Toast_3.jpg?resize=500%2C375",
    "https://www.recipetineats.com/tachyon/2014/06/French-Toast_3.jpg?resize=480%2C270"
  ],
  "recipeYield": [
    "2",
    "2 - 3 people"
  ],
  "prepTime": "PT2M",
  "cookTime": "PT10M",
  "totalTime": "PT12M",
  "recipeIngredient": [
    "6 slices brioche or white sandwich bread (, slightly stale (Note 1))",
    "30 – 40g / 2 – 3 tbsp   butter",
    "2  large eggs ((~60g / 2 oz each))",
    "½ cup / 125 ml  milk",
    "1/2 tsp cinnamon powder",
    "1 tsp vanilla extract",
    "250g / 8 oz  strawberries, halved",
    "1 tbsp white sugar",
    "Maple syrup, butter"
  ],
  "recipeInstructions": [
    {
      "@type": "HowToStep",
      "text": "Whisk together Egg Mixture in a bowl. Vigorous whisk = avoid cinnamon floating on top.",
      "name": "Whisk together Egg Mixture in a bowl. Vigorous whisk = avoid cinnamon floating on top.",
      "url": "https://www.recipetineats.com/french-toast/#wprm-recipe-26510-step-0-0"
    },
    {
      "@type": "HowToStep",
      "text": "Melt 15g / 1 tbsp butter in a non stick skillet over medium heat.",
      "name": "Melt 15g / 1 tbsp butter in a non stick skillet over medium heat.",
      "url": "https://www.recipetineats.com/french-toast/#wprm-recipe-26510-step-0-1"
    },
    {
      "@type": "HowToStep",
      "text": "Dunk a piece of bread quickly into the egg mixture, coating both sides. Place in pan. Repeat with more slices to fill the pan, but don’t crowd it (do 2 or 3 at a time).",
      "name": "Dunk a piece of bread quickly into the egg mixture, coating both sides. Place in pan. Repeat with more slices to fill the pan, but don’t crowd it (do 2 or 3 at a time).",
      "url": "https://www.recipetineats.com/french-toast/#wprm-recipe-26510-step-0-2"
    },
    {
      "@type": "HowToStep",
      "text": "Cook for 2 ½ - 3 minutes on each side until the surface is golden, then transfer to serving plates.",
      "name": "Cook for 2 ½ - 3 minutes on each side until the surface is golden, then transfer to serving plates.",
      "url": "https://www.recipetineats.com/french-toast/#wprm-recipe-26510-step-0-3"
    },
    {
      "@type": "HowToStep",
      "text": "Add more butter into the pan and cook remaining bread.",
      "name": "Add more butter into the pan and cook remaining bread.",
      "url": "https://www.recipetineats.com/french-toast/#wprm-recipe-26510-step-0-4"
    },
    {
      "@type": "HowToStep",
      "text": "Serve with butter and plenty of maple syrup, and Macerated Strawberries if using!",
      "name": "Serve with butter and plenty of maple syrup, and Macerated Strawberries if using!",
      "url": "https://www.recipetineats.com/french-toast/#wprm-recipe-26510-step-0-5"
    },
    {
      "@type": "HowToSection",
      "name": "Macerated Strawberries (optional):",
      "itemListElement": [
        {
          "@type": "HowToStep",
          "text": "Toss strawberries with sugar, set aside for 20 minutes+. The strawberries will soften and sweat, and create a bit of syrup.",
          "name": "Toss strawberries with sugar, set aside for 20 minutes+. The strawberries will soften and sweat, and create a bit of syrup.",
          "url": "https://www.recipetineats.com/french-toast/#wprm-recipe-26510-step-1-0"
        }
      ]
    }
  ],
